const body = $json.body || {};
const invoice_text = typeof body.invoice_text === "string" ? body.invoice_text : "";
const raw = typeof body.raw_response === "string" ? body.raw_response : "";
if (!invoice_text && !raw) {
  throw new Error("Empty request: send invoice_text or raw_response");
}
return { json: { id: body.id ?? null, invoice_text, raw } };

const text = ($json.content && $json.content[0] && $json.content[0].text)
  || $json.text || $json.output
  || Object.values($json).find((v) => typeof v === "string") || "";
return { json: { raw: text } };

const FIELDS = ["invoice_number", "issue_date", "seller_name", "seller_nip",
  "buyer_nip", "net_amount", "vat_rate", "vat_amount", "gross_amount"];
const AMOUNTS = ["net_amount", "vat_amount", "gross_amount"];

function parseJson(raw) {
  const clean = raw.replace(/```json/g, "").replace(/```/g, "").trim();
  const start = clean.indexOf("{");
  const end = clean.lastIndexOf("}");
  const candidates = [clean];
  if (start !== -1 && end > start) candidates.push(clean.slice(start, end + 1));
  for (const c of candidates) {
    try {
      const data = JSON.parse(c);
      if (data && typeof data === "object" && !Array.isArray(data)) return [data, true];
    } catch (e) {}
  }
  return [{}, false];
}

function cleanValue(field, value) {
  if (value === null || value === undefined || typeof value === "object") return null;
  if (typeof value === "boolean") return String(value);
  if (typeof value === "number") {
    if (AMOUNTS.includes(field)) return value.toFixed(2);
    if (field === "vat_rate" && Number.isInteger(value)) return value;
    return String(value);
  }
  const s = String(value).trim();
  return ["", "null", "none"].includes(s.toLowerCase()) ? null : s;
}

const raw = $json.raw || "";
const [data, parseOk] = parseJson(raw);
const record = {};
for (const f of FIELDS) record[f] = cleanValue(f, data[f]);

return {
  json: {
    id: $("Normalize input").item.json.id ?? null,
    parse_ok: parseOk,
    record,
    raw,
  },
};

const FIELDS = ["invoice_number", "issue_date", "seller_name", "seller_nip",
  "buyer_nip", "net_amount", "vat_rate", "vat_amount", "gross_amount"];
const VAT_RATES = [23, 8, 5, 0];
const WEIGHTS = [6, 5, 7, 2, 3, 4, 5, 6, 7];

const isEmpty = (v) => v === null || v === undefined || v === "";

function validNip(value) {
  const s = String(value);
  if (!/^\d{10}$/.test(s)) return false;
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += Number(s[i]) * WEIGHTS[i];
  const check = sum % 11;
  return check !== 10 && check === Number(s[9]);
}

function parseDate(value) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value));
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return y * 10000 + mo * 100 + d;
}

function toCents(value) {
  const s = String(value).trim();
  if (!/^[+-]?\d+(\.\d+)?$/.test(s)) return null;
  return Math.round(Number(s) * 100);
}

function validate(rec) {
  const failures = [];

  if (FIELDS.some((f) => isEmpty(rec[f]))) failures.push("missing_field");

  for (const f of ["seller_nip", "buyer_nip"]) {
    if (!isEmpty(rec[f]) && !validNip(rec[f])) {
      failures.push("nip_checksum");
      break;
    }
  }

  if (!isEmpty(rec.issue_date)) {
    const d = parseDate(rec.issue_date);
    if (d === null) failures.push("date_invalid");
    else if (d < 20250101 || d > 20261231) failures.push("date_range");
  }

  let rate = null;
  if (!isEmpty(rec.vat_rate)) {
    const s = String(rec.vat_rate).trim();
    if (/^[+-]?\d+$/.test(s)) {
      rate = Number(s);
      if (!VAT_RATES.includes(rate)) failures.push("vat_rate_value");
    } else {
      failures.push("vat_rate_format");
    }
  }

  const cents = {};
  for (const k of ["net_amount", "vat_amount", "gross_amount"]) {
    if (isEmpty(rec[k])) { cents[k] = null; continue; }
    cents[k] = toCents(rec[k]);
    if (cents[k] === null) failures.push("amount_format");
  }
  const net = cents.net_amount, vat = cents.vat_amount, gross = cents.gross_amount;

  if (net !== null && vat !== null && gross !== null && Math.abs(net + vat - gross) > 1) {
    failures.push("sum_mismatch");
  }
  if (net !== null && vat !== null && VAT_RATES.includes(rate)) {
    const expected = Math.floor((net * rate + 50) / 100);
    if (Math.abs(vat - expected) > 1) failures.push("vat_mismatch");
  }
  return failures;
}

const { id, parse_ok, record } = $json;
const failures = validate(record);
const route = failures.length === 0 ? "auto" : "review";
if (!parse_ok) failures.unshift("parse_error");

return { json: { id, parse_ok, record, failures, route } };

const r = $json.record;
const s = (v) => (v === null || v === undefined ? "" : String(v));
return { json: {
  invoice_id: s($json.id),
  invoice_number: s(r.invoice_number),
  issue_date: s(r.issue_date),
  seller_name: s(r.seller_name),
  seller_nip: s(r.seller_nip),
  buyer_nip: s(r.buyer_nip),
  net_amount: s(r.net_amount),
  vat_rate: s(r.vat_rate),
  vat_amount: s(r.vat_amount),
  gross_amount: s(r.gross_amount),
  processed_at: new Date().toISOString(),
}};

return { json: {
  invoice_id: $json.id === null || $json.id === undefined ? "" : String($json.id),
  failures: ($json.failures || []).join(";"),
  record_json: JSON.stringify($json.record),
  processed_at: new Date().toISOString(),
}};
